on":"description","type":"paragraph","provenance":"campaign","sourceIds":["ece-current-copy"],"text":"Mapa de la región."}]$verify_a1906c10a6c74ee6$::jsonb and revision=1) union all select 'ece:gm:equipment:owned:personal:chr_116845116f22e81490bfe826e33bd37a:inv_53a3994e4981a78f55381c6884191818' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='gm:equipment:owned:personal:chr_116845116f22e81490bfe826e33bd37a:inv_53a3994e4981a78f55381c6884191818' and payload#>'{rules,definition,description}'=$verify_5cb9d10ee2a8df1b$[{"id":"recovered-campaign-description","text":"Kit de Exploración de Ruinas\nIncluye:\ncinceles;\nmartillos finos;\ncepillos;\ncuerdas;\npoleas.","type":"paragraph","section":"flavor","sourceIds":["ece-campaign-document"],"provenance":"campaign"}]$verify_5cb9d10ee2a8df1b$::jsonb and revision=1) union all select 'ece:gm:equipment:owned:personal:chr_116845116f22e81490bfe826e33bd37a:inv_6468441ce1833cebafdd2a531d6dc09b' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='gm:equipment:owned:personal:chr_116845116f22e81490bfe826e33bd37a:inv_6468441ce1833cebafdd2a531d6dc09b' and payload#>'{rules,definition,description}'=$verify_7b4b61a96e239007$[{"id":"current-description","text":"Objeto narrativo sin bonificación mecánica definida.","type":"paragraph","section":"description","sourceIds":["ece-current-copy"],"provenance":"campaign"},{"id":"recovered-campaign-description","text":"Núcleo Luciente Fragmentado\nUno de los objetos más importantes del grupo.\n\nHistoria\nAños atrás Draven participó en una excavación ilegal financiada por un noble sureño.\nAllí encontró un pequeño núcleo cristalino incrustado en una maquinaria imposible.\nEl mecanismo estaba destruido.\nEl cristal permanecía activo.\nDesde entonces lo estudia obsesivamente.\n\nLo importante\nNi Draven.\nNi Viktor.\nNi Severino.\nComprenden realmente qué es.\nPero Severino sospecha que puede constituir la clave para reproducir ciertos fenómenos observados en artefactos aelorianos.\nPor eso insiste en llevar a Draven en esta expedición.","type":"paragraph","section":"flavor","sourceIds":["ece-campaign-document"],"provenance":"campaign"}]$verify_7b4b61a96e239007$::jsonb and revision=1) union all select 'ece:gm:equipment:owned:personal:chr_116845116f22e81490bfe826e33bd37a:inv_6a6ac05b61e07639932c9c40b37b1521' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='gm:equipment:owned:personal:chr_116845116f22e81490bfe826e33bd37a:inv_6a6ac05b61e07639932c9c40b37b1521' and payload#>'{features}'=$verify_1c6fcc112db180f2$[{"id":"preserved-personal-rule","kind":"other","name":"Reglas de la variante personal","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Bolsa de contención creada mediante Replicar objeto mágico.\n\nEsta bolsa posee un espacio interior considerablemente mayor que sus dimensiones exteriores, que son de 60 cm de diámetro en la abertura y 1,2 m de profundidad. La bolsa puede contener hasta 250 kg, con un volumen máximo de 2 m3. La bolsa pesa 7,5 kg, independientemente de su contenido. Sacar un objeto de la bolsa cuesta una acción.\n\nSi se sobrecarga, perfora o rasga la bolsa, esta se rompe y se destruye, y su contenido se dispersa por el Plano Astral. Si se pone la bolsa del revés, su contenido se vuelca sin sufrir daño, pero la bolsa debe volver a ponerse del derecho antes de usarla de nuevo. Las criaturas que se encuentren en el interior de la bolsa y que necesiten respirar podrán sobrevivir una cantidad de minutos igual a 10 dividida entre el número de criaturas (como mínimo 1 minuto). Después, se ahogarán.\n\nMeter una bolsa de contención en el espacio extradimensional creado por un morral práctico, un agujero portátil o un objeto similar destruye instantáneamente ambos objetos y abre un portal al Plano Astral. El portal se crea en el sitio en el que un objeto se introdujo dentro del otro. El portal absorbe a todas las criaturas que estén a 3 m o menos de él y las conduce a un lugar aleatorio del Plano Astral. Después, el portal se cierra. El portal solo funciona en un sentido y no puede volverse a abrir.","showInActions":false}]$verify_1c6fcc112db180f2$::jsonb and revision=1) union all select 'ece:gm:equipment:owned:personal:chr_116845116f22e81490bfe826e33bd37a:inv_6ebef557e867217868bf2f78d20b7929' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='gm:equipment:owned:personal:chr_116845116f22e81490bfe826e33bd37a:inv_6ebef557e867217868bf2f78d20b7929' and payload#>'{features}'=$verify_d6a42dc5e948e2d8$[{"id":"preserved-personal-rule","kind":"other","name":"Reglas de la variante personal","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Equipo Anti-Troll\nComo parte de la expedición:\nFuego Alquímico ×3\nÁcido ×4\nBombas Incendiarias Experimentales ×2\nDiseñadas específicamente para neutralizar regeneración troll.","showInActions":false}]$verify_d6a42dc5e948e2d8$::jsonb and revision=1) union all select 'ece:gm:equipment:owned:personal:chr_116845116f22e81490bfe826e33bd37a:inv_7041f0940d4df74a167f61890b790b5c' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='gm:equipment:owned:personal:chr_116845116f22e81490bfe826e33bd37a:inv_7041f0940d4df74a167f61890b790b5c' and payload#>'{features}'=$verify_bffc6f31a0ed827b$[{"id":"preserved-personal-rule","kind":"other","name":"Reglas de la variante personal","uses":null,"order":0,"rolls":