profunda de la Infraoscuridad.\nEl cristal:\nemite una luz muy tenue;\nreacciona débilmente a la magia;\nposee vetas internas similares a las observadas en cristales lucientes de superficie.\nCuando Severino lo observa por primera vez durante la expedición, queda profundamente intrigado.\nEste fragmento constituye una de las primeras pistas de que los cristales lucientes existen tanto en la superficie como en las profundidades del mundo, y puede convertirse en una pieza importante para futuras conexiones entre la Infraoscuridad, el Eco y el legado aeloriano.","type":"paragraph","section":"flavor","sourceIds":["ece-campaign-document"],"provenance":"campaign"}]$verify_88442117174e3b38$::jsonb and revision=1) union all select 'ece:gm:equipment:owned:personal:chr_345a4e8763475f1c2acbd5c2a56bcf36:inv_10ffc9c10f35eb8b36b3641a53e7d09c' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='gm:equipment:owned:personal:chr_345a4e8763475f1c2acbd5c2a56bcf36:inv_10ffc9c10f35eb8b36b3641a53e7d09c' and payload#>'{features}'=$verify_bffc6f31a0ed827b$[{"id":"preserved-personal-rule","kind":"other","name":"Reglas de la variante personal","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"","showInActions":false}]$verify_bffc6f31a0ed827b$::jsonb and payload#>'{rules,definition,description}'=$verify_81bc94338984b446$[{"id":"player-description","section":"description","type":"paragraph","provenance":"campaign","sourceIds":["ece-current-copy"],"text":"Pieles para clima extremo."}]$verify_81bc94338984b446$::jsonb and revision=1) union all select 'ece:gm:equipment:owned:personal:chr_345a4e8763475f1c2acbd5c2a56bcf36:inv_3d974cbd3e501ec9a5ecfb8b075df826' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='gm: